/**
 * Try-it samples: real DHARMA passages, so nobody needs inscription text to hand. Two groups
 * (eval/reports/2026-11-02-samples.md):
 * - "masked": a span the editor restored, hidden as [?N] in a VAL benchmark passage; the edition's reading ships with
 *   the sample so Restore can show it after the result (drawn by a pre-declared rule, never from TEST).
 * - "unsolved": TRAIN passages whose gaps the editors themselves left blank; nobody knows the answer.
 * Generated by scripts/build_samples.py (tests/test_samples.py and samples.test.ts check the split rules).
 * Do not edit the JSON by hand.
 */
import { useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import type { Level } from '../lib/levels';
import imagesJson from './sample-images.json';

export type Era = 'pallava' | 'pandya' | 'chola' | 'rashtrakuta' | 'vijayanagara';

export type SampleGroup = 'masked' | 'unsolved';

/** The DHARMA edition's own reading of a masked gap. `norm` is its letters-only form (normalise_for_scoring). */
export interface EditionReading {
  text_iso: string;
  text_tamil: string;
  norm: string;
}

/** What the live restorer returned for one gap of this sample when it was recorded (recorded-restores.json). */
export interface RecordedGap {
  decision: 'fill' | 'abstain';
  proposal_iso: string | null;
  proposal_tamil: string | null;
  confidence: number | null;
  /** masked: match | differs | open; unsolved: filled | open. */
  outcome: 'match' | 'differs' | 'open' | 'filled';
  top_matches?: boolean;
  any_matches?: boolean;
}

export interface Sample {
  id: string;
  group: SampleGroup;
  inscription_id: string;
  /** masked samples come from VAL, unsolved ones from TRAIN; never TEST. */
  split: 'train' | 'val';
  /** unsolved: benchmark/blank.jsonl ids of the gaps (letters lost on the stone, never restored). */
  blank_ids: string[];
  /** masked: the benchmark/items.val.jsonl item whose target is hidden. */
  item_id: string | null;
  hard: boolean | null;
  era: Era;
  era_ta: string;
  era_en: string;
  /** Suggested level for "Learn with this". */
  learn_level: Level;
  title_ta: string;
  title_en: string;
  place_ta: string;
  place_en: string;
  /** The edition's own title: place, ruler and year as DHARMA gives them. */
  edition_title: string;
  ruler: string | null;
  regnal_year: number | null;
  dynasty: string | null;
  why_ta: string;
  why_en: string;
  /** 1-based first and last line of the edition text in this passage. */
  lines: [number, number];
  gaps: number;
  text_iso: string;
  text_tamil: string;
  dharma_url: string;
  source_url: string;
  licence: string;
  licence_url: string;
  /** masked only: what the published edition reads in the gap. */
  edition_reading: EditionReading | null;
  /** 'pending' when the Tamil title and description await a native-speaker check. */
  ta_review: 'pending' | 'done';
  recorded: { date: string; models_used: string[]; gaps: RecordedGap[] } | null;
}

export interface SampleImage {
  id: string;
  /** The source passage (scripts/build_samples.py PICKS) whose text the picture shows; not always in the gallery. */
  sample: string;
  script: 'tamil' | 'iso15919';
  style: 'stone' | 'hero' | 'photo' | 'page';
  title_en: string;
  title_ta: string;
  /** Path under the site root (app/web/public), e.g. "samples/stone-chola.jpg". */
  file: string;
  inscription_id: string;
  lines: string[];
  /** What a perfect read returns: lines joined by "\n"; a chipped patch is [?N] with N only approximate. */
  expected_text: string;
  credit: string;
  dharma_url: string;
  licence: string;
  licence_url: string;
}

// The passages (about 42 kB of JSON) are loaded on demand, in their own chunk, so routes that never show a sample
// do not pay for them. Tests and the mock API import them synchronously from './data'.
export const SAMPLE_IMAGES = imagesJson as SampleImage[];
export const ERAS: Era[] = ['pallava', 'pandya', 'chola', 'rashtrakuta', 'vijayanagara'];

let loading: Promise<Sample[]> | null = null;
let loaded: Sample[] | null = null;

/** Every try-it sample; the first call fetches the chunk, later calls reuse it. */
export function loadSamples(): Promise<Sample[]> {
  loading ??= import('./data').then((m) => (loaded = m.SAMPLES));
  return loading;
}

/** The samples, or null while their chunk loads (or when `enabled` is false, in which case nothing is fetched). */
export function useSamples(enabled = true): Sample[] | null {
  const [samples, setSamples] = useState<Sample[] | null>(loaded);
  useEffect(() => {
    if (samples || !enabled) return;
    let live = true;
    void loadSamples().then((s) => live && setSamples(s));
    return () => {
      live = false;
    };
  }, [samples, enabled]);
  return enabled ? samples : null;
}

export function sampleById(samples: Sample[] | null, id: string | null | undefined): Sample | undefined {
  return id && samples ? samples.find((s) => s.id === id) : undefined;
}

export function sampleByInscription(samples: Sample[] | null, inscriptionId: string | null | undefined): Sample | undefined {
  return inscriptionId && samples ? samples.find((s) => s.inscription_id === inscriptionId) : undefined;
}

/** URL of a sample image, respecting Vite's base path. */
export function sampleImageUrl(image: SampleImage): string {
  return `${import.meta.env.BASE_URL}${image.file}`;
}

/**
 * Letters-only form used to compare a fill with the edition (mirrors ezhuthu.corpus.script.normalise_for_scoring):
 * lower case, ṛ spelled r̥, and everything that is not a letter or a combining mark dropped.
 */
export function normForMatch(s: string): string {
  return s
    .replace(/\[\?\d*\]/g, ' ')
    .normalize('NFC')
    .toLowerCase()
    .replace(/ṛ/g, 'r̥')
    .replace(/[^\p{L}\p{M}]/gu, '')
    .normalize('NFC');
}

export type EditionMatch = 'match' | 'differs' | 'open';

/** How a restore result for a masked gap compares with the edition: the chosen fill, or "open" on an abstain. */
export function compareWithEdition(chosen: string | null | undefined, edition: EditionReading): EditionMatch {
  if (chosen == null) return 'open';
  return normForMatch(chosen) === edition.norm ? 'match' : 'differs';
}

export const restoreHref = (s: Sample) => `/restore?sample=${encodeURIComponent(s.id)}`;
export const learnHref = (s: Sample) =>
  `/practice?inscription=${encodeURIComponent(s.inscription_id)}&level=${s.learn_level}&sample=${encodeURIComponent(s.id)}`;

/**
 * The sample named by `?sample=<id>` on /restore, as the text and script the restore form should start with
 * (null with no `?sample=`, an unknown id, or while the samples load).
 * Tamil script in both UI languages (user feedback: Tamil first); the page shows the English-letter form under it.
 */
export function useRestoreSample(): { sample: Sample; text: string; script: 'tamil' | 'iso15919' } | null {
  const [params] = useSearchParams();
  const id = params.get('sample');
  const samples = useSamples(id != null);
  return useMemo(() => {
    const sample = sampleById(samples, id);
    return sample ? { sample, text: sample.text_tamil, script: 'tamil' as const } : null;
  }, [samples, id]);
}
